	createFakeKiroDB(t, home)
	restore := stubSQLiteRunner(t, func(args ...string) ([]byte, error) {
		switch len(args) {
		case 3: // querySessionID call
			return []byte(`[{"json_extract(value, '$.conversation_id')":"cli-conv"}]`), nil
		case 2: // ensureCachedTranscript call
			return cliTranscript, nil
		default:
			return nil, errors.New("unexpected")
		}
	})
	defer restore()

