func TestEnsureIDETranscriptMatchesByPrompt(t *testing.T) {
	repoRoot := t.TempDir()
	home := t.TempDir()
	cwd := filepath.Join(repoRoot, "workspace")
	t.Setenv("ENTIRE_REPO_ROOT", repoRoot)
	t.Setenv("HOME", home)
	if err := os.MkdirAll(cwd, 0o750); err != nil {
		t.Fatalf("mkdir cwd: %v", err)
	}

	// Multiple IDE sessions — the latest is NOT the one we want
	sessionsDir := createIDEWorkspaceSessionsDirRealEncoding(t, home, cwd)
	index := `[
		{"sessionId":"older-sess","title":"add python hello world - ide","dateCreated":"1774112778524"},
		{"sessionId":"newer-sess","title":"create hello world rust","dateCreated":"1774113530304"}
	]`
	if err := os.WriteFile(filepath.Join(sessionsDir, "sessions.json"), []byte(index), 0o600); err != nil {
		t.Fatalf("write sessions.json: %v", err)
	}
	correctTranscript := `{"history":[{"message":{"role":"user","content":"add python hello world - ide"}},{"message":{"role":"assistant","content":"Created hello.py"}}]}`
	wrongTranscript := `{"history":[{"message":{"role":"user","content":"create hello world rust"}},{"message":{"role":"assistant","content":"Created main.rs"}}]}`
	if err := os.WriteFile(filepath.Join(sessionsDir, "older-sess.json"), []byte(correctTranscript), 0o600); err != nil {
		t.Fatalf("write correct transcript: %v", err)
	}
	if err := os.WriteFile(filepath.Join(sessionsDir, "newer-sess.json"), []byte(wrongTranscript), 0o600); err != nil {
		t.Fatalf("write wrong transcript: %v", err)
	}

	// Cache the prompt from user-prompt-submit
	promptDir := filepath.Join(repoRoot, ".entire", "tmp")
	if err := os.MkdirAll(promptDir, 0o750); err != nil {
		t.Fatalf("mkdir prompt dir: %v", err)
	}
	if err := os.WriteFile(filepath.Join(promptDir, lastPromptFile), []byte("add python hello world - ide"), 0o600); err != nil {
		t.Fatalf("write last prompt: %v", err)
	}

	cachePath, err := New().ensureIDETranscript(cwd, "test-session")
	if err != nil {
		t.Fatalf("ensureIDETranscript() error = %v", err)
	}

	data, err := os.ReadFile(cachePath)
	if err != nil {
		t.Fatalf("read cached transcript: %v", err)
	}
	// Should pick the MATCHING session, not the latest
	if !strings.Contains(string(data), "add python hello world - ide") {
		t.Fatalf("should match session by prompt, got: %s", string(data))
	}
	if strings.Contains(string(data), "create hello world rust") {
		t.Fatal("should NOT pick the latest session when prompt matches an older one")
	}
}

